import { animate, group, query, style, transition, trigger } from '@angular/animations';

const MODAL_QUERY_SELECTOR = {
  OVERLAY: '[modal-overlay]',
  CONTAINER: '[modal-container]',
};
const ANIMATION = {
  TIME: '0.2s',
  TYPE: 'ease-out',
};

export const SKIP_ANIMATION_STATE = 'skipAnimation';
export const NORMAL_ANIMATION_STATE = 'toggleAnimation';

const MODAL_ANIMATION_TRANSITIONS = [
  transition(`void => ${SKIP_ANIMATION_STATE}`, []),
  transition(`${SKIP_ANIMATION_STATE} => void`, []),
  transition(':enter', [
    group([
      query(
        MODAL_QUERY_SELECTOR.OVERLAY,
        style({
          opacity: 0,
        }),
      ),
      query(
        MODAL_QUERY_SELECTOR.CONTAINER,
        style({
          opacity: 0,
          transform: 'translateY(-50%) translateY(-24px)',
        }),
      ),
      query(
        MODAL_QUERY_SELECTOR.OVERLAY,
        animate(`${ANIMATION.TIME} ${ANIMATION.TYPE}`, style({ opacity: 1 })),
      ),
      query(
        MODAL_QUERY_SELECTOR.CONTAINER,
        animate(
          `${ANIMATION.TIME} ${ANIMATION.TYPE}`,
          style({
            opacity: 1,
            transform: 'translateY(-50%)',
          }),
        ),
      ),
    ]),
  ]),
  transition(':leave', [
    group([
      query(
        MODAL_QUERY_SELECTOR.OVERLAY,
        style({
          opacity: 0.4,
        }),
      ),
      query(
        MODAL_QUERY_SELECTOR.CONTAINER,
        style({
          opacity: 1,
          transform: 'translateY(-50%)',
        }),
      ),
      query(
        MODAL_QUERY_SELECTOR.OVERLAY,
        animate(`${ANIMATION.TIME} ${ANIMATION.TYPE}`, style({ opacity: 0 })),
      ),
      query(
        MODAL_QUERY_SELECTOR.CONTAINER,
        animate(
          `${ANIMATION.TIME} ${ANIMATION.TYPE}`,
          style({
            opacity: 0,
            transform: 'translateY(-50%) translateY(24px)',
          }),
        ),
      ),
    ]),
  ]),
];

export const modalAnimation = [trigger('modalToggle', MODAL_ANIMATION_TRANSITIONS)];
