import { A11yModule } from '@angular/cdk/a11y';
import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import { NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChild,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  OnDestroy,
  Output,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  inject,
  numberAttribute,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import {
  QButtonComponent,
  QButtonIconPosition,
  QButtonVariant,
} from '@questrade/allspark-angular-components/button';
import { QScrollShadowDirective } from '@questrade/allspark-angular-components/core/directives';
import { injectDestroy } from '@questrade/allspark-angular-components/core/utils';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import { QLinkDirective } from '@questrade/allspark-angular-components/link';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { arrowBack } from '@questrade/allspark-icons/icons';
import { BehaviorSubject, Observable, takeUntil } from 'rxjs';
import { NORMAL_ANIMATION_STATE, SKIP_ANIMATION_STATE, modalAnimation } from './modal.animation';
import { QModalSize } from './types/modal-size.type';

@Component({
  selector: 'q-modal',
  templateUrl: './modal.component.html',
  styleUrls: ['./modal.component.scss'],
  imports: [
    NgTemplateOutlet,
    A11yModule,
    TranslocoModule,
    QButtonComponent,
    QLinkDirective,
    QInteractiveIconComponent,
    QScrollShadowDirective,
  ],
  providers: [MISSING_KEY_HANDLER, ALLSPARK_SCOPE],
  animations: [modalAnimation],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
/**
 * @deprecated Use Q_DIALOG_COMPONENTS instead, to be removed.
 * @breaking-change First major after Jan 31, 2026
 */
export class QModalComponent implements AfterViewInit, OnDestroy {
  @Output() readonly primaryButtonClicked = new EventEmitter<Event>();
  @Output() readonly secondaryButtonClicked = new EventEmitter<Event>();
  @Output() readonly linkClicked = new EventEmitter<Event>();
  @Output() readonly overlayClicked = new EventEmitter<Event>();
  @Output() readonly escClicked = new EventEmitter<Event>();

  @Input() title = '';
  @Input() size: QModalSize = 'medium';
  @Input() primaryButtonType: QButtonVariant = 'primary';
  @Input() primaryButtonText = '';
  @Input() primaryButtonIcon = '';
  @Input() primaryButtonIconPosition: QButtonIconPosition = 'left';
  @Input() secondaryButtonType: QButtonVariant = 'secondary';
  @Input() secondaryButtonText = '';
  @Input() secondaryButtonIcon = '';
  @Input() secondaryButtonIconPosition: QButtonIconPosition = 'left';
  @Input() linkText = '';
  @Input() linkUrl = '#';
  @Input({ transform: booleanAttribute }) showSecondaryButton = false;
  @Input({ transform: booleanAttribute }) showLink = false;
  @Input({ transform: booleanAttribute }) stackedActionsOnMobile = true;
  @Input({ transform: booleanAttribute }) disablePrimaryButton = false;
  @Input({ transform: booleanAttribute }) disableSecondaryButton = false;
  @Input({ transform: booleanAttribute }) disableLink = false;
  @Input({ transform: booleanAttribute }) showHeader = true;
  @Input({ transform: booleanAttribute }) showFooter = true;
  @Input({ transform: numberAttribute }) @HostBinding('attr.tabindex') tabIndex = 0;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-modal';

  @ContentChild('modalHeaderTemplate') _modalHeaderTemplate!: TemplateRef<HTMLElement>;
  @ContentChild('modalContentTemplate') _modalContentTemplate!: TemplateRef<HTMLElement>;
  @ContentChild('modalFooterTemplate') _modalFooterTemplate!: TemplateRef<HTMLElement>;

  @ViewChild('secondaryButton') _secondaryButton!: QButtonComponent;
  @ViewChild('content') _contentRef!: ElementRef<HTMLElement>;

  @HostBinding('@modalToggle') _modalToggleState: unknown;

  @HostListener('window:resize', []) _onWindowResize(): void {
    this._calculateAnimationState();
  }
  @HostListener('document:keydown.escape', ['$event']) _onKeydownHandler(event: Event): void {
    this.escClicked.emit(event);
  }

  _currentContentTemplate: TemplateRef<HTMLElement> | null = null;
  _boxShadow$: Observable<string> | null = null;
  _containerScrollHeight = 0;
  readonly _rootClass = 'q-modal';

  private _boxShadowClass = 'none';
  private readonly _contentTemplateHistory: (TemplateRef<HTMLElement> | null)[] = [];
  private readonly _boxShadowSubject$ = new BehaviorSubject(this._boxShadowClass);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _breakpointObserver = inject(BreakpointObserver);
  private readonly _destroy$ = injectDestroy();

  constructor() {
    this._iconRegistry.registerIcon(arrowBack);
    this._boxShadow$ = this._boxShadowSubject$.asObservable();
    this._calculateAnimationState();
  }

  ngAfterViewInit(): void {
    this._observeBreakpoints();

    this._contentRef.nativeElement?.focus();

    this._currentContentTemplate = this._modalContentTemplate;
    this._cdr.detectChanges();
    document.body.classList.add('q-modal-visible');
  }

  ngOnDestroy(): void {
    document.body.classList.remove('q-modal-visible');
  }

  showTemplate(template: TemplateRef<HTMLElement>): void {
    if (!template) return;
    this._updateCurrentContentTemplate(template);
  }

  /** @hidden */
  previousContent(): void {
    this._currentContentTemplate = this._contentTemplateHistory.pop() ?? null;
    this._cdr.detectChanges();
  }

  /** @hidden */
  onSecondaryButtonClick(event: Event): void {
    this.secondaryButtonClicked.emit(event);
  }

  /** @hidden */
  onPrimaryButtonClick(event: Event): void {
    this.primaryButtonClicked.emit(event);
  }

  /** @hidden */
  onLinkClicked(event: Event): void {
    if (!this.disableLink) {
      this.linkClicked.emit(event);
    }
  }

  /** @hidden */
  onOverlayClicked(event: Event): void {
    this.overlayClicked.emit(event);
  }

  _calculateAnimationState(): void {
    this._modalToggleState = this.isMobileScreen() ? SKIP_ANIMATION_STATE : NORMAL_ANIMATION_STATE;
  }

  /** @hidden */
  onContainerScroll(event: Event): void {
    const target = event.target as HTMLElement;

    this._containerScrollHeight = target.scrollHeight;
  }

  get isAlternativeContent(): boolean {
    return this._contentTemplateHistory.length > 0;
  }

  private _observeBreakpoints(): void {
    const initialSize = this.size;
    const sizeOrder: QModalSize[] = ['medium', 'large', 'xlarge'];
    const breakpointMap = new Map<string, QModalSize>([
      ['(max-width: 723px)', 'medium'],
      ['(min-width: 724px) and (max-width: 1279px)', 'large'],
      ['(min-width: 1280px)', 'xlarge'],
    ]);
    const breakpointOrder: string[] = [
      '(max-width: 723px)',
      '(min-width: 724px) and (max-width: 1279px)',
      '(min-width: 1280px)',
    ];

    this._breakpointObserver
      .observe(breakpointOrder)
      .pipe(takeUntil(this._destroy$))
      .subscribe((state: BreakpointState) => {
        let potentialSize: QModalSize = initialSize;

        for (const breakpoint of breakpointOrder) {
          if (state.breakpoints[breakpoint]) {
            potentialSize = breakpointMap.get(breakpoint) || initialSize;
            break;
          }
        }

        const initialSizeIndex = sizeOrder.indexOf(initialSize);
        const potentialSizeIndex = sizeOrder.indexOf(potentialSize);

        // The new size should be the smaller of the two (based on index)
        // If initialSize is 'medium' (index 0), it can never be larger.
        // If initialSize is 'large' (index 1), it can be 'medium' or 'large'.
        // If initialSize is 'xlarge' (index 2), it can be 'medium', 'large', or 'xlarge'.
        const newSizeIndex = Math.min(initialSizeIndex, potentialSizeIndex);
        const newSize = sizeOrder[newSizeIndex];

        if (newSize && this.size !== newSize) {
          this.size = newSize;
          this._cdr.markForCheck();
        }
      });
  }

  private isMobileScreen(): boolean {
    return window?.innerWidth <= 599;
  }

  private _updateCurrentContentTemplate(template: TemplateRef<HTMLElement>): void {
    this._contentTemplateHistory.push(this._currentContentTemplate);
    this._currentContentTemplate = template;
    this._cdr.markForCheck();
  }
}
